  7	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
  8	/// (no use-case layer, matching this codebase's existing small-scope
  9	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
 10	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
 11	/// the already-fetched pages survive leaving and re-entering
 12	/// `/meus-registros` within the same app session.
 13	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
 14	  MeusRegistrosCubit(this._repository) : super(const MeusRegistrosLoading());
 15	
 16	  final EntriesRepository _repository;
 17	
 18	  /// A monotonic counter guarding against a stale in-flight call's result
 19	  /// landing after a newer call has already changed the state (e.g. the
 20	  /// user leaves and quickly re-enters `/meus-registros` while a slow
 21	  /// first request is still pending, or taps retry before the original
 22	  /// request resolves). Incremented at the start of every [loadFirstPage],
 23	  /// then captured locally before each `await` in [loadFirstPage]/
 24	  /// [_fetchMore] — a result whose captured generation no longer matches
 25	  /// this counter by the time it resolves is discarded rather than
 26	  /// emitted.
 27	  int _generation = 0;
 28	
 29	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
 30	  /// re-fetches from scratch rather than keeping a previous visit's page
 31	  /// around, since a new entry may have been saved (Insertion Modal, Epic
 32	  /// 3) since the last visit.
 33	  Future<void> loadFirstPage() async {
 34	    final generation = ++_generation;
 35	    emit(const MeusRegistrosLoading());
 36	    final result = await _repository.list();
 37	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
 38	    // can race this awaited call (e.g. a fast app teardown mid-request) —
 39	    // `emit()` after `close()` would otherwise throw.
 40	    if (isClosed || generation != _generation) {
 41	      return;
 42	    }
 43	    result.match(
 44	      (failure) => emit(MeusRegistrosError(message: failure.message)),
 45	      (page) {
 46	        // Same degenerate-cursor distrust as `_fetchMore`'s own guard below:
 47	        // a page reporting zero items is treated as exhausted regardless of
 48	        // `page.nextCursor` — an empty first page with a non-null cursor
 49	        // would otherwise strand the user on `MeusRegistrosEmpty` with no
 50	        // way back to a cursor this state no longer tracks.
 51	        if (page.items.isEmpty) {
 52	          emit(const MeusRegistrosEmpty());
 53	          return;
 54	        }
 55	        emit(
 56	          MeusRegistrosLoaded(
 57	            entries: _dedupedById(page.items),
 58	            nextCursor: page.nextCursor,
 59	          ),
 60	        );
 61	      },
 62	    );
 63	  }
 64	
 65	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
 66	  /// end. A no-op while not [MeusRegistrosLoaded], while
 67	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
 68	  /// already in flight, or — critically — once
 69	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
 70	  /// last guard, a failed page's own footer swapping from a spinner to a
 71	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
 72	  /// just enough to leave the scroll position still inside the
 73	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
 74	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
 75	  /// this screen's own widget test. Once failed, only an explicit
 76	  /// [retryLoadMore] (the footer's own button) tries again.
 77	  Future<void> loadMore() => _fetchMore(isRetry: false);
 78	
 79	  /// The footer's "Tentar novamente" button — the one path allowed to
 80	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
 81	  /// ([loadMore]'s own doc).
 82	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
 83	
 84	  Future<void> _fetchMore({required bool isRetry}) async {
 85	    final current = state;
 86	    if (current is! MeusRegistrosLoaded ||
 87	        current.nextCursor == null ||
 88	        current.isLoadingMore ||
 89	        (current.loadMoreFailed && !isRetry)) {
 90	      return;
 91	    }
 92	    final generation = _generation;
 93	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
 94	    final result = await _repository.list(cursor: current.nextCursor);
 95	    if (isClosed || generation != _generation) {
 96	      return;
 97	    }
 98	    // Re-reads `state` rather than closing over `current` — defensive
 99	    // against `loadFirstPage()` having reset the state to something other
100	    // than `MeusRegistrosLoaded` while this await was pending.
101	    final latest = state;
102	    if (latest is! MeusRegistrosLoaded) {
103	      return;
104	    }
105	    result.match(
106	      (failure) =>
107	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
108	      (page) {
109	        // I/O matrix: "Next page appended, no dup ids" — defensive
110	        // de-duplication in case a cursor-boundary entry is ever repeated
111	        // by the server, including a repeat *within* this same page
112	        // (`_dedupedById`'s running `seenIds` set covers both).
113	        final seenIds = latest.entries.map((entry) => entry.id).toSet();
114	        final newEntries = _dedupedById(page.items, seenIds: seenIds);
115	        // Defensive guard against a degenerate server response: if every
116	        // item in this "successful" page was already present by id (zero
117	        // genuinely-new entries) yet the server still reports a non-null
118	        // `nextCursor`, treat the page as exhausted rather than trusting
119	        // that cursor — otherwise a misbehaving/stuck server cursor could
120	        // make the scroll listener keep re-triggering `loadMore()`
121	        // indefinitely with no progress.
122	        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
123	        emit(
124	          MeusRegistrosLoaded(
125	            entries: [...latest.entries, ...newEntries],
126	            nextCursor: nextCursor,
127	          ),
128	        );
129	      },
130	    );
131	  }
132	}
133	
134	/// Filters [entries] down to the first occurrence of each id, checked
135	/// against [seenIds] (default empty) — covers both a duplicate against an
136	/// already-held id *and* a duplicate within [entries] itself, since
137	/// [seenIds] accumulates as entries are walked.
138	List<Entry> _dedupedById(List<Entry> entries, {Set<String>? seenIds}) {
139	  final seen = seenIds ?? <String>{};
140	  return [
141	    for (final entry in entries)
142	      if (seen.add(entry.id)) entry,
143	  ];
144	}

