 3	/// Story 1.5 — lets `core/network`'s `ApiClient` signal a mid-session
 4	/// `AUTH_EXPIRED` without importing anything from `features/auth` (RNF06:
 5	/// the domain/data layers of a feature are the only things allowed to know
 6	/// about each other across that boundary, never the other way from core).
 7	/// `SessionRepositoryImpl` is the one bridge that turns an event on
 8	/// [expiredEvents] into the epic's single `SessionStatus.expired` value on
 9	/// its own `statusStream` (Design Notes).
10	///
11	/// Pure Dart, no Flutter import — same constraint `ApiClient`/`Failure`
12	/// already hold in `core/`.
13	abstract class SessionExpiryNotifier {
14	  /// Broadcast stream of expiry events. Unlike `SessionRepository
15	  /// .statusStream`, this carries no replay semantics: it is a one-shot
16	  /// signal per expiry, not a status a late subscriber needs to catch up
17	  /// on — only `SessionRepositoryImpl`'s single long-lived subscription
18	  /// (wired at construction) is expected to listen.
19	  Stream<void> get expiredEvents;
20	
21	  /// Signals that the current session just expired mid-use (a non-boot
22	  /// `AUTH_EXPIRED` response). Never throws.
23	  void notifyExpired();
24	
25	  /// Releases the underlying stream resource.
26	  Future<void> dispose();
27	}
28	
29	/// Default implementation — a broadcast `StreamController` wrapped behind
30	/// the port above.
31	class SessionExpiryNotifierImpl implements SessionExpiryNotifier {
32	  final StreamController<void> _controller = StreamController<void>.broadcast();
33	
34	  @override
35	  Stream<void> get expiredEvents => _controller.stream;
36	
37	  @override
38	  void notifyExpired() {
39	    // Guards against a call racing `dispose()` (wired to `get_it`'s
40	    // `sl.reset()`) — without this, a late `.add()` after `.close()` would
41	    // throw an unhandled `StateError` instead of just being a no-op on an
42	    // already-torn-down notifier (same rationale as `SessionRepositoryImpl
43	    // ._emit`).
44	    if (_controller.isClosed) {
45	      return;
46	    }
47	    _controller.add(null);
48	  }
49	
50	  @override
51	  Future<void> dispose() => _controller.close();
52	}

